import { Effect, Layer } from 'effect'
import {
  type PreparedRuntimeProvider,
  type PreparedRuntimeProviders,
  RuntimeError,
  RuntimeExecutor,
  RuntimeHost,
  RuntimePlanner,
  RuntimeProviderRegistry,
  RuntimeState,
  type RuntimeCapabilityKind,
  type RuntimeExecutionRequest,
  type RuntimeExecutionResult,
  type RuntimeMetadata,
  type RuntimePlan,
  type RuntimeCapabilityProvider,
  type RuntimeProviderPrepareInput,
  type TrustedExecutionContext,
} from '@hrbr/runtime-core'
import { Telemetry } from '@hrbr/telemetry'

type RuntimeProviderRequirement = {
  readonly kind: RuntimeCapabilityKind
  readonly key: string
  readonly metadata?: RuntimeMetadata | undefined
  readonly optional?: boolean | undefined
}

const requirementKey = (requirement: RuntimeProviderRequirement): string =>
  requirement.kind + ':' + requirement.key

const runtimeProviderRequirements = (plan: RuntimePlan): RuntimeProviderRequirement[] => {
  const requirements = new Map<string, RuntimeProviderRequirement>()
  for (const namespace of plan.requiredNamespaces) {
    const requirement = {
      kind: namespace.bindingKind,
      key: namespace.namespace,
      optional: namespace.optional,
    }
    requirements.set(requirementKey(requirement), requirement)
  }
  for (const capability of plan.capabilities) {
    const requirement = {
      kind: capability.kind,
      key: capability.key,
      metadata: capability.metadata,
    }
    requirements.set(requirementKey(requirement), requirement)
  }
  return Array.from(requirements.values())
}

const normalizePreparedProviders = (
  prepared: PreparedRuntimeProvider | ReadonlyArray<PreparedRuntimeProvider>
): ReadonlyArray<PreparedRuntimeProvider> => {
  if (Array.isArray(prepared)) return prepared as ReadonlyArray<PreparedRuntimeProvider>
  return [prepared as PreparedRuntimeProvider]
}

const prepareRequirement = (
  providerByKind: ReadonlyMap<RuntimeCapabilityKind, RuntimeCapabilityProvider>,
  requirement: RuntimeProviderRequirement,
  plan: RuntimePlan,
  context: TrustedExecutionContext
): Effect.Effect<ReadonlyArray<PreparedRuntimeProvider>, RuntimeError> => {
  const provider = providerByKind.get(requirement.kind)
  if (!provider) {
    if (requirement.optional) return Effect.succeed([])
    return Effect.fail(
      new RuntimeError(
        'provider',
        'No runtime provider registered for ' + requirement.kind + ' capability',
        requirement
      )
    )
  }

  const input: RuntimeProviderPrepareInput = {
    kind: requirement.kind,
    key: requirement.key,
    plan,
    context,
    metadata: requirement.metadata,
    optional: requirement.optional,
  }
  return provider.prepare(input).pipe(Effect.map(normalizePreparedProviders))
}

const disposePreparedProviders = (
  providerByKind: ReadonlyMap<RuntimeCapabilityKind, RuntimeCapabilityProvider>,
  prepared: PreparedRuntimeProviders
): Effect.Effect<void, RuntimeError> =>
  Effect.gen(function* () {
    for (const preparedProvider of prepared.providers) {
      const provider = providerByKind.get(preparedProvider.kind)
      if (!provider?.dispose) continue
      yield* provider.dispose(preparedProvider)
    }
  })

const releasePreparedProviders = (
  providerByKind: ReadonlyMap<RuntimeCapabilityKind, RuntimeCapabilityProvider>,
  prepared: PreparedRuntimeProviders
): Effect.Effect<void> =>
  disposePreparedProviders(providerByKind, prepared).pipe(Effect.catch(() => Effect.void))

export const makeRuntimeProviderRegistry = (
  providers: ReadonlyArray<RuntimeCapabilityProvider>
): RuntimeProviderRegistry => {
  const providerByKind = new Map<RuntimeCapabilityKind, RuntimeCapabilityProvider>()
  for (const provider of providers) providerByKind.set(provider.kind, provider)

  return {
    prepare: (
      plan: RuntimePlan,
      context: TrustedExecutionContext
    ): Effect.Effect<PreparedRuntimeProviders, RuntimeError> =>
      Effect.gen(function* () {
        const prepared: PreparedRuntimeProvider[] = []
        for (const requirement of runtimeProviderRequirements(plan)) {
          prepared.push(...(yield* prepareRequirement(providerByKind, requirement, plan, context)))
        }
        return { providers: prepared }
      }),
    prepareScoped: (plan: RuntimePlan, context: TrustedExecutionContext) =>
      Effect.gen(function* () {
        const prepared: PreparedRuntimeProvider[] = []
        for (const requirement of runtimeProviderRequirements(plan)) {
          const acquired = yield* Effect.acquireRelease(
            prepareRequirement(providerByKind, requirement, plan, context),
            (preparedProviders) =>
              releasePreparedProviders(providerByKind, { providers: preparedProviders })
          )
          prepared.push(...acquired)
        }
        return { providers: prepared }
      }),
    dispose: (prepared: PreparedRuntimeProviders): Effect.Effect<void, RuntimeError> =>
      disposePreparedProviders(providerByKind, prepared),
  }
}

export const RuntimeProviderRegistryLive = (providers: ReadonlyArray<RuntimeCapabilityProvider>) =>
  Layer.succeed(RuntimeProviderRegistry, makeRuntimeProviderRegistry(providers))

export const RuntimeExecutorLive = Layer.effect(
  RuntimeExecutor,
  Effect.gen(function* () {
    const planner = yield* RuntimePlanner
    const providerRegistry = yield* RuntimeProviderRegistry
    const host = yield* RuntimeHost
    const state = yield* RuntimeState
    const telemetry = yield* Telemetry

    return {
      execute: (
        request: RuntimeExecutionRequest,
        context: TrustedExecutionContext
      ): Effect.Effect<RuntimeExecutionResult, RuntimeError> =>
        Effect.gen(function* () {
          const startedAt = Date.now()
          const planning = yield* planner.plan(request, context)
          const plan = planning.runtimePlan

          yield* state.record({
            name: 'runtime.plan.created',
            time: new Date(startedAt).toISOString(),
            detail: plan,
          })

          const run = Effect.scoped(
            Effect.gen(function* () {
              const prepared = yield* providerRegistry.prepareScoped(plan, context)
              const result = yield* host.invoke({
                request,
                context,
                plan,
                hostPlan: planning.hostPlan,
                providers: prepared,
              })
              yield* state.record({
                name: 'runtime.host.finished',
                time: new Date().toISOString(),
                detail: { mode: result.mode },
              })
              return {
                ...result,
                timings: {
                  ...result.timings,
                  totalMs: Date.now() - startedAt,
                },
              }
            })
          ).pipe(Effect.ensuring(state.flush().pipe(Effect.catch(() => Effect.void))))

          return yield* telemetry.span(
            { name: 'runtime.execute', attributes: { mode: request.mode } },
            run
          )
        }),
    }
  })
)
