import { Effect, Layer } from 'effect'
import {
  RuntimeArtifacts,
  type RuntimeArtifactWrite,
  RuntimeError,
  type RuntimeHostInvocation,
  RuntimeHost,
  RuntimeProviderRegistry,
  RuntimeState,
  type RuntimeArtifactRef,
  type RuntimeExecutionResult,
  type RuntimeStateEvent,
} from '@hrbr/runtime-core'
import {
  type LocalRuntimeArtifactStoreSnapshot,
  makeLocalRuntimeArtifactStore,
} from '@hrbr/runtime-artifacts'
import { type LocalRuntimeStatePortSnapshot, makeLocalRuntimeStatePort } from '@hrbr/runtime-state'
import { TelemetryNoopLive } from '@hrbr/telemetry'

export type LocalRuntimeHostHandler = (
  invocation: RuntimeHostInvocation
) => Effect.Effect<RuntimeExecutionResult, RuntimeError>

export type LocalRuntimeHostCallback = (
  invocation: RuntimeHostInvocation
) => RuntimeExecutionResult | Promise<RuntimeExecutionResult>

export const makeLocalRuntimeHostHandler =
  (callback: LocalRuntimeHostCallback): LocalRuntimeHostHandler =>
  (invocation) =>
    Effect.tryPromise({
      try: async () => await callback(invocation),
      catch: (cause) =>
        new RuntimeError('host', cause instanceof Error ? cause.message : String(cause), { cause }),
    })

interface LocalRuntimeProvidersOptions {
  readonly host?: LocalRuntimeHostHandler | undefined
}

export interface LocalRuntimeStateSnapshot {
  readonly events: ReadonlyArray<RuntimeStateEvent>
  readonly artifacts: ReadonlyArray<RuntimeArtifactRef>
  readonly statePort: LocalRuntimeStatePortSnapshot
  readonly artifactStore: LocalRuntimeArtifactStoreSnapshot
}

const localRuntimeArtifactRef = (
  artifact: RuntimeArtifactWrite,
  index: number
): RuntimeArtifactRef => ({
  id: 'local-artifact-' + String(index),
  kind: artifact.kind,
  contentType: artifact.contentType,
  sizeBytes: artifact.body.byteLength,
  ...(artifact.metadata ? { metadata: artifact.metadata } : {}),
})

const defaultLocalRuntimeHost: LocalRuntimeHostHandler = (invocation) =>
  Effect.succeed({
    mode: invocation.request.mode,
    result: undefined,
    logs: [],
    warnings: [],
    timings: {},
  })

const makeLocalRuntimeHostLayer = (handler: LocalRuntimeHostHandler) =>
  Layer.succeed(RuntimeHost, {
    invoke: handler,
  })

export const makeInMemoryLocalRuntimeProviders = (options: LocalRuntimeProvidersOptions = {}) => {
  const events: RuntimeStateEvent[] = []
  const artifacts: RuntimeArtifactRef[] = []
  const statePort = makeLocalRuntimeStatePort()
  const artifactStorePort = makeLocalRuntimeArtifactStore()
  const hostHandler = options.host ?? defaultLocalRuntimeHost

  const state = Layer.succeed(RuntimeState, {
    record: (event) =>
      Effect.sync(() => {
        events.push(event)
      }),
    flush: () => Effect.void,
  })

  const artifactStore = Layer.succeed(RuntimeArtifacts, {
    put: (artifact) =>
      Effect.sync(() => {
        const ref = localRuntimeArtifactRef(artifact, artifacts.length + 1)
        artifacts.push(ref)
        return ref
      }),
  })

  const registry = Layer.succeed(RuntimeProviderRegistry, {
    prepare: () => Effect.succeed({ providers: [] }),
    prepareScoped: () => Effect.succeed({ providers: [] }),
    dispose: () => Effect.void,
  })

  const host = makeLocalRuntimeHostLayer(hostHandler)

  return {
    layers: Layer.mergeAll(
      state,
      artifactStore,
      statePort.layer,
      artifactStorePort.layer,
      registry,
      host,
      TelemetryNoopLive
    ),
    snapshot: (): LocalRuntimeStateSnapshot => ({
      events,
      artifacts,
      statePort: statePort.snapshot(),
      artifactStore: artifactStorePort.snapshot(),
    }),
  }
}

export const makeLocalRuntimeProviders = makeInMemoryLocalRuntimeProviders
