const LOCAL_PROJECT_MANIFEST_VERSION = 1
const LOCAL_STORE_SCHEMA_VERSION = 1

type SqlValue = string | number | null

interface LocalSqliteStatement {
  run(...params: SqlValue[]): unknown
  get(...params: SqlValue[]): unknown
  all(...params: SqlValue[]): unknown[]
}

interface LocalSqliteDatabase {
  exec(sql: string): void
  prepare(sql: string): LocalSqliteStatement
  close(): void
}

type LocalSqliteDatabaseCtor = new (filename: string) => LocalSqliteDatabase

let sqliteCtor: LocalSqliteDatabaseCtor | null = null
let sqliteWarningPatched = false

