const schemaSql = `
  CREATE TABLE IF NOT EXISTS local_workspaces (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    slug TEXT NOT NULL,
    created_by TEXT NOT NULL,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
  );

  CREATE TABLE IF NOT EXISTS local_runs (
    id TEXT PRIMARY KEY,
    workspace_id TEXT NOT NULL,
    mode TEXT NOT NULL,
    status TEXT NOT NULL,
    code_sha256 TEXT NOT NULL,
    request_json TEXT NOT NULL,
    result_json TEXT,
    error TEXT,
    created_at TEXT NOT NULL,
    completed_at TEXT,
    FOREIGN KEY (workspace_id) REFERENCES local_workspaces(id)
  );

  CREATE INDEX IF NOT EXISTS idx_local_runs_workspace_created
    ON local_runs(workspace_id, created_at DESC);

  CREATE TABLE IF NOT EXISTS local_runtime_events (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    run_id TEXT NOT NULL,
    name TEXT NOT NULL,
    time TEXT NOT NULL,
    detail_json TEXT,
    FOREIGN KEY (run_id) REFERENCES local_runs(id)
  );

  CREATE INDEX IF NOT EXISTS idx_local_runtime_events_run_id
    ON local_runtime_events(run_id, id);

  CREATE TABLE IF NOT EXISTS local_artifacts (
    id TEXT PRIMARY KEY,
    run_id TEXT NOT NULL,
    kind TEXT NOT NULL,
    content_type TEXT,
    path TEXT,
    size_bytes INTEGER,
    metadata_json TEXT,
    created_at TEXT NOT NULL,
    FOREIGN KEY (run_id) REFERENCES local_runs(id)
  );
`

const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === 'object' && value !== null && !Array.isArray(value)

const sha256Hex = (value: string): string => createHash('sha256').update(value).digest('hex')

const tokenHint = (token: string): string => {
  if (token.length <= 8) return '*'.repeat(token.length)
  return token.slice(0, 4) + '...' + token.slice(-4)
}

const compareSecret = (candidate: string, expected: string): boolean => {
  const candidateHash = Buffer.from(sha256Hex(candidate), 'hex')
  const expectedHash = Buffer.from(sha256Hex(expected), 'hex')
  return (
    candidateHash.length === expectedHash.length && timingSafeEqual(candidateHash, expectedHash)
  )
}

const nowIso = (now: (() => Date) | undefined): string => (now ? now() : new Date()).toISOString()

const slugify = (value: string): string => {
  const slug = value
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
  return slug.length > 0 ? slug : 'local'
}

const randomId = (prefix: string): string => prefix + '_' + randomBytes(10).toString('hex')

const writeJson = (path: string, value: unknown): void => {
  writeFileSync(path, JSON.stringify(value, null, 2) + '\n', { mode: 0o600 })
}

const readJson = (path: string): unknown => JSON.parse(readFileSync(path, 'utf8'))

const manifestStorePath = (layout: LocalProjectLayout): string => {
  const path = layout.store.path
  const relativePath = relative(layout.harborDir, path)
  if (relativePath.length > 0 && !relativePath.startsWith('..') && !isAbsolute(relativePath)) {
    return relativePath
  }
  return path
}

const resolveManifestStorePath = (harborDir: string, manifest: LocalRuntimeManifest): string => {
  const path = manifest.store.path
  return isAbsolute(path) ? path : resolve(harborDir, path)
}

const validateManifest = (value: unknown): LocalRuntimeManifest => {
  if (!isRecord(value)) throw new Error('Invalid local Harbor runtime manifest')
  const version = value.version
  const project = value.project
  const store = value.store
  if (version !== LOCAL_PROJECT_MANIFEST_VERSION || !isRecord(project) || !isRecord(store)) {
    throw new Error('Invalid local Harbor runtime manifest')
  }
  const workspaceId = project.workspaceId
  const workspaceName = project.workspaceName
  const slug = project.slug
  const createdAt = project.createdAt
  const updatedAt = project.updatedAt
  const driver = store.driver
  const path = store.path
  if (
    typeof workspaceId !== 'string' ||
    typeof workspaceName !== 'string' ||
    typeof slug !== 'string' ||
    typeof createdAt !== 'string' ||
    typeof updatedAt !== 'string' ||
    driver !== 'sqlite' ||
    typeof path !== 'string'
  ) {
    throw new Error('Invalid local Harbor runtime manifest')
  }
  const auth = value.auth
  if (auth !== undefined) {
    if (
      !isRecord(auth) ||
      typeof auth.tokenSha256 !== 'string' ||
      typeof auth.tokenHint !== 'string'
    ) {
      throw new Error('Invalid local Harbor auth manifest')
    }
    return {
      version: LOCAL_PROJECT_MANIFEST_VERSION,
      project: { workspaceId, workspaceName, slug, createdAt, updatedAt },
      store: { driver, path },
      auth: {
        tokenSha256: auth.tokenSha256,
        tokenHint: auth.tokenHint,
      },
    }
  }
  return {
    version: LOCAL_PROJECT_MANIFEST_VERSION,
    project: { workspaceId, workspaceName, slug, createdAt, updatedAt },
    store: { driver, path },
  }
}

export const resolveLocalProjectLayout = (
  rootDir: string,
  options: { readonly storePath?: string | undefined } = {}
): LocalProjectLayout => {
  const root = resolve(rootDir)
  const harborDir = join(root, '.harbor')
  const storePath = resolve(options.storePath ?? join(harborDir, 'harbor.db'))
  return {
    rootDir: root,
    harborDir,
    runtimeManifestPath: join(harborDir, 'runtime.json'),
    artifactsDir: join(harborDir, 'artifacts'),
    tracesDir: join(harborDir, 'traces'),
    cacheDir: join(harborDir, 'cache'),
    gitignorePath: join(harborDir, '.gitignore'),
    store: { path: storePath },
  }
}

export const createLocalStoreHandle = (path: string): LocalStoreHandle => ({ path: resolve(path) })

export const initLocalProject = (options: InitLocalProjectOptions = {}): LocalProjectHandle => {
  const rootDir = resolve(options.rootDir ?? process.cwd())
  const layout = resolveLocalProjectLayout(rootDir, { storePath: options.storePath })
  const timestamp = nowIso(options.now)
  const workspaceName = options.workspaceName ?? 'Local Harbor'
  const workspaceId = options.workspaceId ?? randomId('ws_local')
  const slug = options.slug ?? slugify(workspaceName)

  mkdirSync(layout.harborDir, { recursive: true })
  mkdirSync(dirname(layout.store.path), { recursive: true })
  mkdirSync(layout.artifactsDir, { recursive: true })
  mkdirSync(layout.tracesDir, { recursive: true })
  mkdirSync(layout.cacheDir, { recursive: true })
  if (!existsSync(layout.gitignorePath)) {
    writeFileSync(layout.gitignorePath, '*\n!.gitignore\n', { mode: 0o600 })
  }

  const manifestBase: Omit<LocalRuntimeManifest, 'auth'> = {
    version: LOCAL_PROJECT_MANIFEST_VERSION,
    project: {
      workspaceId,
      workspaceName,
      slug,
      createdAt: timestamp,
      updatedAt: timestamp,
    },
    store: {
      driver: 'sqlite' as const,
      path: manifestStorePath(layout),
    },
  }
  const manifest: LocalRuntimeManifest = options.authToken
    ? {
        ...manifestBase,
        auth: {
          tokenSha256: sha256Hex(options.authToken),
          tokenHint: tokenHint(options.authToken),
        },
      }
    : manifestBase

  writeJson(layout.runtimeManifestPath, manifest)

  const store = openLocalHarborStore(layout.store)
  try {
    store.upsertWorkspace(localWorkspaceFromManifest(manifest))
  } finally {
    store.close()
  }

  return { rootDir, layout, manifest }
}

export const discoverLocalProject = (
  options: DiscoverLocalProjectOptions = {}
): LocalProjectHandle | null => {
  let current = resolve(options.startDir ?? process.cwd())
  while (true) {
    const harborDir = join(current, '.harbor')
    const runtimeManifestPath = join(harborDir, 'runtime.json')
    if (existsSync(runtimeManifestPath)) {
      const manifest = validateManifest(readJson(runtimeManifestPath))
      const layout = resolveLocalProjectLayout(current, {
        storePath: resolveManifestStorePath(harborDir, manifest),
      })
      return { rootDir: current, layout, manifest }
    }
    const parent = dirname(current)
    if (parent === current) return null
    current = parent
  }
}

export const localWorkspaceFromManifest = (
  manifest: LocalRuntimeManifest
): LocalWorkspaceRecord => ({
  id: manifest.project.workspaceId,
  name: manifest.project.workspaceName,
  slug: manifest.project.slug,
  createdBy: 'local',
  createdAt: manifest.project.createdAt,
  updatedAt: manifest.project.updatedAt,
})

const adaptBunSqlite = (BunDb: new (filename: string) => unknown): LocalSqliteDatabaseCtor => {
  type BunStatement = {
    run: (...params: unknown[]) => unknown
    get: (...params: unknown[]) => unknown
    all: (...params: unknown[]) => unknown[]
  }
  type BunDatabase = {
    exec: (sql: string) => void
    prepare: (sql: string) => BunStatement
    close: () => void
  }

  return class AdaptedBunSqlite {
    private readonly bun: BunDatabase

    constructor(filename: string) {
      this.bun = new BunDb(filename) as BunDatabase
    }

    exec(sql: string): void {
      this.bun.exec(sql)
    }

    prepare(sql: string): LocalSqliteStatement {
      const statement = this.bun.prepare(sql)
      return {
        run: (...params) => statement.run(...params),
        get: (...params) => statement.get(...params),
        all: (...params) => statement.all(...params),
      }
    }

    close(): void {
      this.bun.close()
    }
  }
}

const loadSqliteDatabaseCtor = (): LocalSqliteDatabaseCtor => {
  if (sqliteCtor) return sqliteCtor
  if (!sqliteWarningPatched) {
    sqliteWarningPatched = true
    const original = process.emitWarning.bind(process)
    process.emitWarning = ((warning, ...rest: unknown[]) => {
      const text =
        typeof warning === 'string'
          ? warning
          : warning instanceof Error
            ? warning.message
            : String(warning)
      if (/SQLite is an experimental feature/i.test(text)) return
      return (original as (...args: unknown[]) => void)(warning, ...rest)
    }) as typeof process.emitWarning
  }
  const req = createRequire(import.meta.url)
  try {
    const sqlite = req('node:sqlite') as { DatabaseSync: LocalSqliteDatabaseCtor }
    sqliteCtor = sqlite.DatabaseSync
    return sqliteCtor
  } catch {
    const bunSqlite = req('bun:sqlite') as { Database: new (filename: string) => unknown }
    sqliteCtor = adaptBunSqlite(bunSqlite.Database)
    return sqliteCtor
  }
}

const tightenStorePermissions = (storePath: string): void => {
  for (const path of [storePath, storePath + '-wal', storePath + '-shm']) {
    try {
      if (existsSync(path)) chmodSync(path, 0o600)
    } catch {
      // Permission tightening is best-effort; failing to chmod must not corrupt the store.
    }
  }
}

const openSqlite = (handle: LocalStoreHandle): LocalSqliteDatabase => {
  mkdirSync(dirname(handle.path), { recursive: true })
  const Sqlite = loadSqliteDatabaseCtor()
  const db = new Sqlite(handle.path)
  db.exec('PRAGMA journal_mode = WAL;')
  db.exec('PRAGMA busy_timeout = 30000;')
  db.exec('PRAGMA foreign_keys = ON;')
  db.exec(schemaSql)
  const version = db.prepare('PRAGMA user_version').get() as
    | { readonly user_version?: number }
    | undefined
  if (!version?.user_version || version.user_version < LOCAL_STORE_SCHEMA_VERSION) {
    db.exec('PRAGMA user_version = ' + String(LOCAL_STORE_SCHEMA_VERSION) + ';')
  }
  tightenStorePermissions(handle.path)
  return db
}

const parseJsonValue = (value: string | null): unknown => {
  if (value === null) return null
  return JSON.parse(value)
}

const toWorkspaceRecord = (row: LocalWorkspaceRow): LocalWorkspaceRecord => ({
  id: row.id,
  name: row.name,
  slug: row.slug,
  createdBy: row.created_by,
  createdAt: row.created_at,
  updatedAt: row.updated_at,
})

const toRunRecord = (row: LocalRunRow): LocalRunRecord => ({
  id: row.id,
  workspaceId: row.workspace_id,
  mode: row.mode,
  status: row.status,
  codeSha256: row.code_sha256,
  request: parseJsonValue(row.request_json),
  result: parseJsonValue(row.result_json),
  error: row.error,
  createdAt: row.created_at,
  completedAt: row.completed_at,
})

const toRuntimeEventRecord = (row: LocalRuntimeEventRow): LocalRuntimeEventRecord => ({
  id: row.id,
  runId: row.run_id,
  name: row.name,
  time: row.time,
  detail: parseJsonValue(row.detail_json),
})

const boundedLimit = (limit: number | undefined): number => {
  if (!Number.isFinite(limit ?? Number.NaN)) return 50
  return Math.max(1, Math.min(100, Math.floor(limit as number)))
}

const boundedOffset = (offset: number | undefined): number => {
  if (!Number.isFinite(offset ?? Number.NaN)) return 0
  return Math.max(0, Math.floor(offset as number))
}

export const openLocalHarborStore = (handle: LocalStoreHandle): LocalHarborStore => {
  const normalizedHandle = createLocalStoreHandle(handle.path)
  const db = openSqlite(normalizedHandle)

  return {
    handle: normalizedHandle,
    schemaVersion: () => {
      const row = db.prepare('PRAGMA user_version').get() as
        | { readonly user_version?: number }
        | undefined
      return row?.user_version ?? 0
    },
    upsertWorkspace: (workspace) => {
      db.prepare(
        `INSERT INTO local_workspaces (id, name, slug, created_by, created_at, updated_at)
         VALUES (?, ?, ?, ?, ?, ?)
         ON CONFLICT(id) DO UPDATE SET
           name = excluded.name,
           slug = excluded.slug,
           updated_at = excluded.updated_at`
      ).run(
        workspace.id,
        workspace.name,
        workspace.slug,
        workspace.createdBy,
        workspace.createdAt,
        workspace.updatedAt
      )
      tightenStorePermissions(normalizedHandle.path)
    },
    getWorkspace: (workspaceId) => {
      const row = db.prepare('SELECT * FROM local_workspaces WHERE id = ?').get(workspaceId) as
        | LocalWorkspaceRow
        | undefined
      return row ? toWorkspaceRecord(row) : null
    },
    listWorkspaces: (options = {}) => {
      const limit = boundedLimit(options.limit)
      const offset = boundedOffset(options.offset)
      const totalRow = db.prepare('SELECT COUNT(*) AS total FROM local_workspaces').get() as
        | { readonly total?: number }
        | undefined
      const total = totalRow?.total ?? 0
      const rows = db
        .prepare('SELECT * FROM local_workspaces ORDER BY created_at ASC LIMIT ? OFFSET ?')
        .all(limit, offset) as LocalWorkspaceRow[]
      return {
        data: rows.map(toWorkspaceRecord),
        total,
        limit,
        offset,
        hasMore: offset + rows.length < total,
      }
    },
    recordRunStarted: (run) => {
      db.prepare('DELETE FROM local_runtime_events WHERE run_id = ?').run(run.id)
      db.prepare(
        `INSERT INTO local_runs
          (id, workspace_id, mode, status, code_sha256, request_json, result_json, error, created_at, completed_at)
         VALUES (?, ?, ?, 'running', ?, ?, NULL, NULL, ?, NULL)
         ON CONFLICT(id) DO UPDATE SET
           workspace_id = excluded.workspace_id,
           mode = excluded.mode,
           status = excluded.status,
           code_sha256 = excluded.code_sha256,
           request_json = excluded.request_json,
           result_json = NULL,
           error = NULL,
           created_at = excluded.created_at,
           completed_at = NULL`
      ).run(
        run.id,
        run.workspaceId,
        run.mode,
        sha256Hex(run.code),
        JSON.stringify(run.request),
        run.createdAt
      )
      tightenStorePermissions(normalizedHandle.path)
    },
    recordRunCompleted: (run) => {
      db.prepare(
        `UPDATE local_runs
         SET status = ?, result_json = ?, error = ?, completed_at = ?
         WHERE id = ?`
      ).run(run.status, JSON.stringify(run.result), run.error ?? null, run.completedAt, run.id)
      tightenStorePermissions(normalizedHandle.path)
    },
    recordRuntimeEvents: (runId, events) => {
      const statement = db.prepare(
        `INSERT INTO local_runtime_events (run_id, name, time, detail_json)
         VALUES (?, ?, ?, ?)`
      )
      for (const event of events) {
        statement.run(
          runId,
          event.name,
          event.time,
          event.detail === undefined ? null : JSON.stringify(event.detail)
        )
      }
      tightenStorePermissions(normalizedHandle.path)
    },
    listRuns: (workspaceId) => {
      const rows = db
        .prepare('SELECT * FROM local_runs WHERE workspace_id = ? ORDER BY created_at DESC')
        .all(workspaceId) as LocalRunRow[]
      return rows.map(toRunRecord)
    },
    getRun: (runId) => {
      const row = db.prepare('SELECT * FROM local_runs WHERE id = ?').get(runId) as
        | LocalRunRow
        | undefined
      return row ? toRunRecord(row) : null
    },
    listRuntimeEvents: (runId) => {
      const rows = db
        .prepare('SELECT * FROM local_runtime_events WHERE run_id = ? ORDER BY id ASC')
        .all(runId) as LocalRuntimeEventRow[]
      return rows.map(toRuntimeEventRecord)
    },
    close: () => {
      db.close()
    },
  }
}

const apiSuccess = (data: unknown, status = 200): Response =>
  jsonResponse({ success: true, data }, status)

const apiFailure = (
  status: number,
  error: string,
  issues?: ReadonlyArray<string> | undefined
): Response => {
  const body = issues ? { success: false, error, issues } : { success: false, error }
  return jsonResponse(body, status)
}

const jsonResponse = (body: unknown, status = 200): Response =>
  new Response(JSON.stringify(body), {
    status,
    headers: {
      'content-type': 'application/json; charset=utf-8',
    },
  })

const textResponse = (body: string, contentType: string, status = 200): Response =>
  new Response(body, {
    status,
    headers: {
      'content-type': contentType,
    },
  })

const parseBody = async (request: Request): Promise<unknown> => {
  if (request.method === 'GET' || request.method === 'HEAD') return undefined
  const text = await request.text()
  if (text.trim().length === 0) return {}
  return JSON.parse(text)
}

const requireRecordBody = (body: unknown): Record<string, unknown> => {
  if (body === undefined) return {}
  if (!isRecord(body)) throw new LocalHttpError(400, 'Expected JSON object request body')
  return body
}

const requireString = (body: Record<string, unknown>, key: string): string => {
  const value = body[key]
  if (typeof value !== 'string' || value.length === 0) {
    throw new LocalHttpError(400, 'Missing required string field: ' + key)
  }
  return value
}

const optionalString = (body: Record<string, unknown>, key: string): string | undefined => {
  const value = body[key]
  return typeof value === 'string' && value.length > 0 ? value : undefined
}

const optionalNumber = (body: Record<string, unknown>, key: string): number | undefined => {
  const value = body[key]
  return typeof value === 'number' && Number.isFinite(value) ? value : undefined
}

const executeSources = (body: Record<string, unknown>): string[] | undefined => {
  const sources = body.sources
  if (!Array.isArray(sources)) return undefined
  return sources.flatMap((source) =>
    isRecord(source) && typeof source.namespace === 'string' ? [source.namespace] : []
  )
}

const executeInputs = (body: Record<string, unknown>): RuntimeMountedInput[] | undefined => {
  const inputs = body.execution_inputs
  if (!Array.isArray(inputs)) return undefined
  return inputs.flatMap((input) => {
    if (
      !isRecord(input) ||
      typeof input.path !== 'string' ||
      typeof input.data_base64 !== 'string'
    ) {
      return []
    }
    const mounted: RuntimeMountedInput = {
      name: input.path,
      data: input.data_base64,
      ...(typeof input.content_type === 'string' ? { contentType: input.content_type } : {}),
      ...(typeof input.sha256 === 'string' ? { sha256: input.sha256 } : {}),
    }
    return [mounted]
  })
}

const executeMode = (body: Record<string, unknown>): RuntimeExecutionMode => {
  const mode = body.mode
  return mode === 'workflow' ? 'workflow' : 'exec'
}

const makeRequest = (input: string | Request | URL, init?: RequestInit): Request => {
  if (input instanceof Request) return init ? new Request(input, init) : input
  return new Request(input, init)
}

const normalizedPath = (url: URL): string => {
  const path = url.pathname.replace(/\/+$/, '') || '/'
  return path.startsWith('/v1/') ? path.slice(3) : path
}

const workspaceSummary = (workspace: LocalWorkspaceRecord) => ({
  id: workspace.id,
  name: workspace.name,
  slug: workspace.slug,
  role: 'owner' as const,
  onboarded_at: null,
  created_at: workspace.createdAt,
  updated_at: workspace.updatedAt,
})

const workspaceDetail = (workspace: LocalWorkspaceRecord) => ({
  id: workspace.id,
  name: workspace.name,
  slug: workspace.slug,
  created_by: workspace.createdBy,
  created_at: workspace.createdAt,
  updated_at: workspace.updatedAt,
})

const runtimeHostNotConfigured: LocalRuntimeHostHandler = (invocation) =>
  Effect.succeed({
    mode: invocation.request.mode,
    error: 'NOT_IMPLEMENTED_LOCAL: no local runtime host configured',
    logs: [],
    warnings: [],
    timings: {},
  })

const executeResultMode = (mode: RuntimeExecutionMode): 'dynamic_worker' | 'workflow' =>
  mode === 'workflow' ? 'workflow' : 'dynamic_worker'

const localWarning = (message: string) => ({
  namespace: 'local',
  tool: 'runtime',
  message,
})

const readBearerToken = (request: Request): string | null => {
  const authorization = request.headers.get('authorization')
  const match = authorization?.match(/^Bearer\s+(.+)$/i)
  return match?.[1] ?? null
}

const authorize = (
  request: Request,
  options: { readonly authToken?: string | undefined; readonly requireAuth: boolean }
): Response | null => {
  if (!options.requireAuth) return null
  if (!options.authToken) {
    return apiFailure(500, 'LOCAL_AUTH_MISCONFIGURED: requireAuth needs authToken')
  }
  const bearer = readBearerToken(request)
  if (!bearer || !compareSecret(bearer, options.authToken)) {
    return apiFailure(401, 'Unauthorized')
  }
  return null
}

export const createLocalHarborFetch = (
  options: CreateLocalHarborFetchOptions
): LocalHarborFetchHandler => {
  if (options.store && options.storeHandle) {
    throw new Error('Pass either store or storeHandle, not both')
  }
  const store =
    options.store ?? openLocalHarborStore(options.storeHandle ?? options.project.layout.store)
  const ownsStore = !options.store
  const now = options.now
  const workspace = localWorkspaceFromManifest(options.project.manifest)
  store.upsertWorkspace(workspace)
  const requireAuth = options.requireAuth ?? options.authToken !== undefined
  const frontend = options.frontend ?? {}
  const runtimeHost = options.runtimeHost ?? runtimeHostNotConfigured
  const planner =
    options.planner ??
    ((request: RuntimeExecutionRequest, context) =>
      Effect.succeed({
        runtimePlan: emptyRuntimePlan({
          requiredNamespaces: (request.sourceFilter ?? []).map((namespace) => ({
            namespace,
            bindingKind: 'tool' as const,
            optional: true,
          })),
        }),
        hostPlan: {
          platform: 'local',
          workspaceId: context.scopeId,
          storePath: store.handle.path,
        },
      }))

  const handleWorkspaceList = async (request: Request): Promise<Response> => {
    const body = requireRecordBody(await parseBody(request))
    const limit = optionalNumber(body, 'limit')
    const offset = optionalNumber(body, 'offset')
    const list = store.listWorkspaces({ limit, offset })
    return apiSuccess({
      data: list.data.map(workspaceSummary),
      total: list.total,
      limit: list.limit,
      offset: list.offset,
      hasMore: list.hasMore,
    })
  }

  const handleWorkspaceGet = async (request: Request): Promise<Response> => {
    const body = requireRecordBody(await parseBody(request))
    const workspaceId = requireString(body, 'workspace_id')
    const found = store.getWorkspace(workspaceId)
    if (!found) return apiFailure(404, 'Workspace not found')
    return apiSuccess(workspaceDetail(found))
  }

  const handleExecute = async (request: Request): Promise<Response> => {
    const body = requireRecordBody(await parseBody(request))
    const workspaceId = requireString(body, 'workspace_id')
    const workspaceRecord = store.getWorkspace(workspaceId)
    if (!workspaceRecord) return apiFailure(404, 'Workspace not found')
    const code = requireString(body, 'code')
    const mode = executeMode(body)
    const runId = optionalString(body, 'run_id') ?? randomId('run_local')
    const createdAt = nowIso(now)
    const timeoutMs = optionalNumber(body, 'timeout_ms')
    const sourceFilter = executeSources(body)
    const executionInputList = executeInputs(body)
    const runtimeRequest: RuntimeExecutionRequest = {
      code,
      mode,
      ...(timeoutMs !== undefined ? { timeoutMs } : {}),
      ...(sourceFilter ? { sourceFilter } : {}),
      ...(executionInputList ? { executionInputs: executionInputList } : {}),
    }

    store.recordRunStarted({
      id: runId,
      workspaceId,
      mode,
      code,
      request: body,
      createdAt,
    })

    const localRuntime = makeInMemoryLocalRuntimeProviders({ host: runtimeHost })
    const runtimeLayer = RuntimeExecutorLive.pipe(
      Layer.provide(
        Layer.mergeAll(
          localRuntime.layers,
          Layer.succeed(RuntimePlanner, {
            plan: planner,
          })
        )
      )
    )
    const runtimeResult: RuntimeExecutionResult = await Effect.runPromise(
      RuntimeExecutor.use((executor) =>
        executor.execute(runtimeRequest, {
          scopeId: workspaceId,
          runId,
        })
      ).pipe(Effect.provide(runtimeLayer))
    ).catch((error: unknown) => ({
      mode,
      error: error instanceof Error ? error.message : String(error),
      logs: [],
      warnings: [],
      timings: {},
    }))

    const status = runtimeResult.error ? 'failed' : 'completed'
    store.recordRuntimeEvents(runId, localRuntime.snapshot().events)
    store.recordRunCompleted({
      id: runId,
      status,
      result: runtimeResult.result ?? null,
      error: runtimeResult.error,
      completedAt: nowIso(now),
    })

    return apiSuccess({
      result: runtimeResult.result ?? null,
      ...(runtimeResult.error ? { error: runtimeResult.error } : {}),
      logs: runtimeResult.logs,
      mode: executeResultMode(mode),
      ...(runtimeResult.warnings.length > 0
        ? { warnings: runtimeResult.warnings.map(localWarning) }
        : {}),
      run_id: runId,
    })
  }

  const handleRunsList = async (request: Request): Promise<Response> => {
    const body = requireRecordBody(await parseBody(request))
    const workspaceId = requireString(body, 'workspace_id')
    return apiSuccess({
      runs: store.listRuns(workspaceId),
    })
  }

  const handleRunsGet = async (request: Request): Promise<Response> => {
    const body = requireRecordBody(await parseBody(request))
    const runId = requireString(body, 'run_id')
    const run = store.getRun(runId)
    if (!run) return apiFailure(404, 'Run not found')
    return apiSuccess({ run })
  }

  const handleRunsEvents = async (request: Request): Promise<Response> => {
    const body = requireRecordBody(await parseBody(request))
    const runId = requireString(body, 'run_id')
    return apiSuccess({
      events: store.listRuntimeEvents(runId),
    })
  }

  const fetchImpl: typeof fetch = async (input, init) => {
    const request = makeRequest(input, init)
    const url = new URL(request.url)
    const path = normalizedPath(url)

    if (request.method === 'GET' && frontend !== false && (path === '/' || path === '/local')) {
      return textResponse(
        renderLocalHarborFrontendHtml({
          ...frontend,
          authRequired: requireAuth,
        }),
        'text/html; charset=utf-8'
      )
    }

    if (
      request.method === 'GET' &&
      frontend !== false &&
      path === LOCAL_HARBOR_FRONTEND_SCRIPT_PATH
    ) {
      return textResponse(renderLocalHarborFrontendScript(), 'text/javascript; charset=utf-8')
    }

    if (request.method === 'GET' && (path === '/health' || path === '/v1/health')) {
      return jsonResponse({
        status: 'ok',
        service: 'harbor-api',
        environment: 'local',
      })
    }

    if (request.method === 'GET' && (path === '/healthz' || path === '/v1/healthz')) {
      const startedAt = Date.now()
      return jsonResponse({
        status: 'ok',
        service: 'harbor-api',
        environment: 'local',
        version: null,
        checks: {
          db: 'ok',
          migrations: 'ok',
        },
        migrations: {
          expected: String(LOCAL_STORE_SCHEMA_VERSION),
          latest_applied: String(store.schemaVersion()),
          applied_count: store.schemaVersion() >= LOCAL_STORE_SCHEMA_VERSION ? 1 : 0,
        },
        db_ms: 0,
        total_ms: Date.now() - startedAt,
        timestamp: nowIso(now),
      })
    }

    const authFailure = authorize(request, { authToken: options.authToken, requireAuth })
    if (authFailure) return authFailure

    try {
      if (request.method === 'POST' && path === '/workspaces/list')
        return await handleWorkspaceList(request)
      if (request.method === 'POST' && path === '/workspaces/get')
        return await handleWorkspaceGet(request)
      if (request.method === 'POST' && path === '/plugins/execute')
        return await handleExecute(request)
      if (request.method === 'POST' && path === '/runs/list') return await handleRunsList(request)
      if (request.method === 'POST' && path === '/runs/get') return await handleRunsGet(request)
      if (request.method === 'POST' && path === '/runs/events')
        return await handleRunsEvents(request)
      return apiFailure(501, 'NOT_IMPLEMENTED_LOCAL: ' + request.method + ' ' + path)
    } catch (error) {
      if (error instanceof LocalHttpError)
        return apiFailure(error.status, error.message, error.issues)
      if (error instanceof SyntaxError) return apiFailure(400, 'Invalid JSON request body')
      return apiFailure(500, error instanceof Error ? error.message : String(error))
    }
  }

  return {
    project: options.project,
    store,
    fetch: fetchImpl,
    close: () => {
      if (ownsStore) store.close()
    },
  }
}

const incomingHeaders = (request: IncomingMessage): Headers => {
  const headers = new Headers()
  for (const [key, value] of Object.entries(request.headers)) {
    if (value === undefined) continue
    if (Array.isArray(value)) {
      for (const item of value) headers.append(key, item)
    } else {
      headers.set(key, value)
    }
  }
  return headers
}

const incomingBody = async (request: IncomingMessage): Promise<ArrayBuffer | undefined> => {
  if (request.method === 'GET' || request.method === 'HEAD') return undefined
  const chunks: Buffer[] = []
  for await (const chunk of request) {
    chunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk))
  }
  if (chunks.length === 0) return undefined
  const body = Buffer.concat(chunks)
  return body.buffer.slice(body.byteOffset, body.byteOffset + body.byteLength)
}

const incomingRequest = async (request: IncomingMessage): Promise<Request> => {
  const host = request.headers.host ?? '127.0.0.1'
  const url = new URL(request.url ?? '/', 'http://' + host)
  const body = await incomingBody(request)
  return new Request(url, {
    method: request.method ?? 'GET',
    headers: incomingHeaders(request),
    ...(body ? { body } : {}),
  })
}

const writeFetchResponse = async (
  fetchResponse: Response,
  response: ServerResponse
): Promise<void> => {
  response.statusCode = fetchResponse.status
  fetchResponse.headers.forEach((value, key) => {
    response.setHeader(key, value)
  })
  const body = await fetchResponse.arrayBuffer()
  response.end(Buffer.from(body))
}

const serverUrl = (server: Server, hostname: string): string => {
  const address = server.address()
  if (!address || typeof address === 'string') return 'http://' + hostname
  const info = address as AddressInfo
  return 'http://' + hostname + ':' + String(info.port)
}

export const startLocalHarborServer = async (
  options: StartLocalHarborServerOptions
): Promise<LocalHarborServer> => {
  const local = createLocalHarborFetch(options)
  const hostname = options.hostname ?? '127.0.0.1'
  const port = options.port ?? 0
  const server = createServer((incoming, outgoing) => {
    void incomingRequest(incoming)
      .then((request) => local.fetch(request))
      .then((response) => writeFetchResponse(response, outgoing))
      .catch((error: unknown) => {
        const response = apiFailure(500, error instanceof Error ? error.message : String(error))
        return writeFetchResponse(response, outgoing)
      })
  })

  try {
    await new Promise<void>((resolveListen, rejectListen) => {
      const onError = (error: Error) => {
        server.off('listening', onListening)
        rejectListen(error)
      }
      const onListening = () => {
        server.off('error', onError)
        resolveListen()
      }
      server.once('error', onError)
      server.once('listening', onListening)
      server.listen(port, hostname)
    })
  } catch (error) {
    local.close()
    throw error
  }

  return {
    project: local.project,
    store: local.store,
    fetch: local.fetch,
    server,
    url: serverUrl(server, hostname),
    close: async () => {
      await new Promise<void>((resolveClose, rejectClose) => {
        server.close((error) => {
          if (error) rejectClose(error)
          else resolveClose()
        })
      })
      local.close()
    },
  }
}
