import { Context, Effect, Layer, Schema } from 'effect'
import { RuntimeError, RuntimeMetadata } from '@hrbr/runtime-core'

export const RuntimeStateEventKind = Schema.Literals([
  'run_event',
  'tool_call',
  'orbit_usage',
  'warning',
  'timing',
  'final_result',
])
export type RuntimeStateEventKind = typeof RuntimeStateEventKind.Type

export const RuntimeStateBaseEvent = Schema.Struct({
  kind: RuntimeStateEventKind,
  time: Schema.String,
  runId: Schema.String,
  scopeId: Schema.String,
  agentId: Schema.optional(Schema.String),
  rootSpanId: Schema.optional(Schema.String),
  metadata: Schema.optional(RuntimeMetadata),
})
export type RuntimeStateBaseEvent = typeof RuntimeStateBaseEvent.Type

export const RuntimeRunStateEvent = Schema.Struct({
  ...RuntimeStateBaseEvent.fields,
  kind: Schema.Literal('run_event'),
  name: Schema.String,
  status: Schema.optional(Schema.String),
})
export type RuntimeRunStateEvent = typeof RuntimeRunStateEvent.Type

export const RuntimeToolCallStateEvent = Schema.Struct({
  ...RuntimeStateBaseEvent.fields,
  kind: Schema.Literal('tool_call'),
  sourceId: Schema.String,
  sourceNamespace: Schema.String,
  toolId: Schema.String,
  title: Schema.optional(Schema.String),
  status: Schema.String,
  durationMs: Schema.optional(Schema.Number),
  input: Schema.optional(Schema.Unknown),
  output: Schema.optional(Schema.Unknown),
  error: Schema.optional(Schema.String),
  contentType: Schema.optional(Schema.String),
  upstreamStatus: Schema.optional(Schema.Number),
})
export type RuntimeToolCallStateEvent = typeof RuntimeToolCallStateEvent.Type

export const RuntimeOrbitUsageStateEvent = Schema.Struct({
  ...RuntimeStateBaseEvent.fields,
  kind: Schema.Literal('orbit_usage'),
  operation: Schema.String,
  key: Schema.optional(Schema.String),
  model: Schema.optional(Schema.String),
  sizeBytes: Schema.optional(Schema.Number),
  durationMs: Schema.Number,
  error: Schema.optional(Schema.String),
})
export type RuntimeOrbitUsageStateEvent = typeof RuntimeOrbitUsageStateEvent.Type

export const RuntimeWarningStateEvent = Schema.Struct({
  ...RuntimeStateBaseEvent.fields,
  kind: Schema.Literal('warning'),
  namespace: Schema.optional(Schema.String),
  tool: Schema.optional(Schema.String),
  message: Schema.String,
})
export type RuntimeWarningStateEvent = typeof RuntimeWarningStateEvent.Type

export const RuntimeTimingStateEvent = Schema.Struct({
  ...RuntimeStateBaseEvent.fields,
  kind: Schema.Literal('timing'),
  name: Schema.String,
  durationMs: Schema.Number,
})
export type RuntimeTimingStateEvent = typeof RuntimeTimingStateEvent.Type

export const RuntimeFinalResultStateEvent = Schema.Struct({
  ...RuntimeStateBaseEvent.fields,
  kind: Schema.Literal('final_result'),
  status: Schema.Literals(['completed', 'failed', 'cancelled']),
  durationMs: Schema.optional(Schema.Number),
  result: Schema.optional(Schema.Unknown),
  error: Schema.optional(Schema.String),
  artifactCount: Schema.optional(Schema.Number),
})
export type RuntimeFinalResultStateEvent = typeof RuntimeFinalResultStateEvent.Type

export const RuntimeStructuredStateEvent = Schema.Union([
  RuntimeRunStateEvent,
  RuntimeToolCallStateEvent,
  RuntimeOrbitUsageStateEvent,
  RuntimeWarningStateEvent,
  RuntimeTimingStateEvent,
  RuntimeFinalResultStateEvent,
])
export type RuntimeStructuredStateEvent = typeof RuntimeStructuredStateEvent.Type

export interface RuntimeStatePort {
  readonly record: (event: RuntimeStructuredStateEvent) => Effect.Effect<void, RuntimeError>
  readonly flush: () => Effect.Effect<void, RuntimeError>
}

export const RuntimeStatePort = Context.Service<RuntimeStatePort>(
  '@hrbr/runtime-state/RuntimeStatePort'
)

export interface RuntimeStateWriteQueue<TWrite> {
  readonly push: (write: TWrite) => void
  readonly drain: () => readonly TWrite[]
  readonly size: () => number
  readonly snapshot: () => readonly TWrite[]
}

export function createRuntimeStateWriteQueue<TWrite>(): RuntimeStateWriteQueue<TWrite> {
  const writes: TWrite[] = []
  return {
    push: (write) => {
      writes.push(write)
    },
    drain: () => writes.splice(0, writes.length),
    size: () => writes.length,
    snapshot: () => writes.slice(),
  }
}

export interface RuntimeStateFlushInfo {
  readonly batchSize: number
  readonly durationMs: number
}

export interface RuntimeStateWriteFlushOptions<TWrite> {
  readonly queue: RuntimeStateWriteQueue<TWrite>
  readonly flush: (writes: readonly TWrite[]) => Promise<void>
  readonly now?: (() => number) | undefined
  readonly schedule?: ((work: Promise<void>) => void) | undefined
  readonly onEmpty?: (() => void) | undefined
  readonly onSuccess?: ((info: RuntimeStateFlushInfo) => void) | undefined
  readonly onFailure?: ((error: unknown, info: RuntimeStateFlushInfo) => void) | undefined
}

export function flushRuntimeStateWriteQueue<TWrite>(
  options: RuntimeStateWriteFlushOptions<TWrite>
): void {
  const batch = options.queue.drain()
  if (batch.length === 0) {
    options.onEmpty?.()
    return
  }
  const now = options.now ?? Date.now
  const startedAt = now()
  const work = Promise.resolve()
    .then(() => options.flush(batch))
    .then(
      () => {
        options.onSuccess?.({ batchSize: batch.length, durationMs: now() - startedAt })
      },
      (error: unknown) => {
        options.onFailure?.(error, {
          batchSize: batch.length,
          durationMs: now() - startedAt,
        })
      }
    )
  if (options.schedule) options.schedule(work)
  else void work
}

export interface LocalRuntimeStatePortSnapshot {
  readonly events: ReadonlyArray<RuntimeStructuredStateEvent>
  readonly flushCount: number
}

export function makeLocalRuntimeStatePort() {
  const events: RuntimeStructuredStateEvent[] = []
  let flushCount = 0
  const layer = Layer.succeed(RuntimeStatePort, {
    record: (event) =>
      Effect.sync(() => {
        events.push(event)
      }),
    flush: () =>
      Effect.sync(() => {
        flushCount += 1
      }),
  })
  return {
    layer,
    snapshot: (): LocalRuntimeStatePortSnapshot => ({
      events: events.slice(),
      flushCount,
    }),
  }
}
